import {Game,CHARACTERS,WEAPONS,WAVE_TOTALS,clamp} from './sim.js';
import {Renderer,drawPerson} from './render.js';
import {stickVector,aimAngle,assistedAngle} from './controls.js';
import {touchLayout,FloatingStick} from './layout.js';
const $=id=>document.getElementById(id),show=id=>$(id).classList.remove('hidden'),hide=id=>$(id).classList.add('hidden');
const SAVE='deadlight-hollow-run-v1',META='deadlight-hollow-records-v1',SETTINGS='deadlight-hollow-settings-v1';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
const remove=key=>{try{localStorage.removeItem(key)}catch{}};
let settings={sound:true,low:false,assist:true,controlSize:'medium',controlReach:'edge',controlOpacity:35,...read(SETTINGS,{})};
if(!['small','medium','large'].includes(settings.controlSize))settings.controlSize='medium';
if(!['edge','inward'].includes(settings.controlReach))settings.controlReach='edge';
settings.controlOpacity=clamp(Number(settings.controlOpacity)||35,15,70);
let uiLayout=null,viewOffset={x:0,y:0};
let records={best:0,wins:0,...read(META,{})};
let selected='ivy',game=new Game(),paused=false,helpFrom='menu',shopTab='arsenal',lastTime=0,lastHud=0,saveTimer=0,bannerTimer=0,tutorialTimer=0,hudSignature='',toastTimeout,saveWarned=false;
const renderer=new Renderer($('world'));renderer.low=settings.low;
const input={mx:0,my:0,angle:0,fire:false};const keys=new Set();let mouse={x:0,y:0,down:false,seen:false};let move={x:0,y:0,power:0},aim={x:0,y:0,power:0};let padPrevious=[];
const isTouch=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0;if(isTouch)document.body.classList.add('touch');
class Sound{
 constructor(){this.ctx=null;this.lastShot=0;}
 boot(){if(!settings.sound)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch{}}
 tone(freq,duration=.07,type='sine',volume=.025,end=freq){if(!settings.sound||!this.ctx||this.ctx.state!=='running')return;let ctx=this.ctx,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),ctx.currentTime+duration);g.gain.setValueAtTime(volume,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);}
 play(type,weapon){if(type==='shoot'){let now=performance.now();if(now-this.lastShot<70)return;this.lastShot=now;let w=WEAPONS[weapon];this.tone(w?.melee?120:w?.blast?90:240,.075,'triangle',.026,w?.melee?55:55);}if(type==='hurt')this.tone(90,.16,'sawtooth',.025,45);if(type==='heal'){this.tone(420,.18,'sine',.04,750);}if(type==='purchase'){this.tone(650,.12,'sine',.04,950);}if(type==='wave'){this.tone(180,.5,'triangle',.025,90);}if(type==='clear'||type==='won'){this.tone(330,.4,'sine',.045,660);setTimeout(()=>this.tone(660,.35,'sine',.025,880),160);}if(type==='dash')this.tone(180,.1,'triangle',.025,520);if(type==='loaded')this.tone(540,.035,'square',.009,660);}
}
const sound=new Sound();
function toast(message){$('toast').textContent=message;show('toast');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>hide('toast'),2600);}
function save(){if(!['wave','scavenge','shop'].includes(game.phase))return;let okay=write(SAVE,game.snapshot());if(!okay&&!saveWarned){toast('Saving is unavailable in this browser session.');saveWarned=true;}}
function hasSave(){let d=read(SAVE,null);if(!d)return false;try{Game.restore(d);return true}catch{remove(SAVE);return false}}
function place(el,box){el.style.left=box.x+'px';el.style.top=box.y+'px';el.style.width=box.w+'px';el.style.height=box.h+'px';}
function applyTouchLayout(){
 let safe={};if(typeof getComputedStyle==='function'){let c=getComputedStyle($('safeAreaProbe'));safe={left:parseFloat(c.paddingLeft)||0,right:parseFloat(c.paddingRight)||0,top:parseFloat(c.paddingTop)||0,bottom:parseFloat(c.paddingBottom)||0};}
 uiLayout=touchLayout(renderer.width,renderer.height,safe,settings.controlSize,settings.controlReach);
 document.documentElement.style.setProperty('--idle-opacity',settings.controlOpacity/100);
 if(!isTouch)return;
 for(let [id,box]of [['moveStick',uiLayout.move],['aimStick',uiLayout.aim]]){let el=$(id);place(el,box);el.style.setProperty('--stick-home-x',box.cx+'px');el.style.setProperty('--stick-home-y',box.cy+'px');el.style.setProperty('--stick-diameter',uiLayout.ring*2+'px');}
 for(let [id,box]of [['dashButton',uiLayout.dash],['healButton',uiLayout.heal],['turretButton',uiLayout.sentry],['weaponDock',uiLayout.dock]])place($(id),box);
}
function resize(){let vv=window.visualViewport,w=Math.round(vv?.width||window.innerWidth),h=Math.round(vv?.height||window.innerHeight),changed=w!==renderer.width||h!==renderer.height;
 viewOffset={x:vv?.offsetLeft||0,y:vv?.offsetTop||0};let st=document.documentElement.style;st.setProperty('--view-width',w+'px');st.setProperty('--view-height',h+'px');st.setProperty('--view-left',viewOffset.x+'px');st.setProperty('--view-top',viewOffset.y+'px');renderer.resize(w,h);applyTouchLayout();if(changed)resetInput();}
window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);window.visualViewport?.addEventListener('scroll',resize);document.addEventListener('fullscreenchange',resize);resize();
function updateSettings(){write(SETTINGS,settings);$('menuSound').textContent=settings.sound?'Sound on ♪':'Sound off';$('soundToggle').textContent=settings.sound?'Sound on ♪':'Sound off';$('qualityToggle').textContent=settings.low?'Quality: battery saver':'Quality: full';$('aimAssist').checked=settings.assist;renderer.low=settings.low;$('controlSize').value=settings.controlSize;$('controlReach').value=settings.controlReach;$('controlOpacity').value=settings.controlOpacity;$('opacityValue').textContent=settings.controlOpacity+'%';applyTouchLayout();}
function toggleSound(){settings.sound=!settings.sound;sound.boot();updateSettings();}
$('menuSound').onclick=toggleSound;$('soundToggle').onclick=toggleSound;$('qualityToggle').onclick=()=>{settings.low=!settings.low;updateSettings();resize();};$('aimAssist').onchange=()=>{settings.assist=$('aimAssist').checked;updateSettings();};updateSettings();
function renderCharacters(){
 $('characters').innerHTML=CHARACTERS.map(c=>`<button class="character-card ${c.id===selected?'selected':''}" data-character="${c.id}" aria-pressed="${c.id===selected}" aria-label="${c.name}, ${c.role}. ${c.description}"><canvas width="128" height="160" aria-hidden="true"></canvas><span><b>${c.name}</b><small>${c.role}</small></span><span class="check">✦</span></button>`).join('');
 for(let b of $('characters').children){let c=b.querySelector('canvas').getContext('2d');drawPerson(c,64,134,b.dataset.character,2.3,0,-.4);}
 $('characterPerk').textContent=CHARACTERS.find(c=>c.id===selected).perk;
}
$('characters').onclick=e=>{let b=e.target.closest('[data-character]');if(!b)return;selected=b.dataset.character;game.resetPlayer(selected);renderCharacters();sound.play('loaded');};renderCharacters();
function title(){$('start').dataset.confirm='';save();paused=false;resetInput();for(let id of ['hud','shop','pause','end','help','controls','displayHelp'])hide(id);show('menu');game=new Game();game.resetPlayer(selected);$('recordWave').textContent=records.best;$('recordWins').textContent=records.wins;$('resume').classList.toggle('hidden',!hasSave());$('start').textContent=hasSave()?'Start a new run →':'Enter the hollow →';}
function begin(){if(hasSave()&&!$('resume').classList.contains('hidden')){ // An explicit second tap protects an existing run.
 if($('start').dataset.confirm!=='yes'){$('start').dataset.confirm='yes';$('start').textContent='Replace saved run →';toast('Tap again to replace your saved run.');return;}}
 $('start').dataset.confirm='';remove(SAVE);game=new Game();game.start(selected,$('difficulty').value);paused=false;resetInput();for(let id of ['menu','shop','pause','end','help','controls','displayHelp'])hide(id);show('hud');sound.boot();tutorialTimer=5;$('tutorial').textContent=isTouch?'Drag in either lower corner · Tap ammo to reload · Pause to adjust controls':'WASD to move · Mouse to aim & fire · Space to dash';show('tutorial');processEvents();save();hudSignature='';updateHud();}
$('start').onclick=begin;
$('resume').onclick=()=>{try{game=Game.restore(read(SAVE,null));selected=game.character;paused=false;resetInput();hide('menu');show('hud');sound.boot();hudSignature='';if(game.phase==='shop'){shopTab='arsenal';openShop();}else{setPause(true);$('pause').querySelector('.eyebrow').textContent='WELCOME BACK';}updateHud();}catch{remove(SAVE);title();toast('That save could not be restored. Start a new run.');}};
function setPause(value){if(!game.roaming)return;paused=value;resetInput();if(!value){hide('controls');hide('displayHelp');hide('help');}if(value){save();show('pause');hide('tutorial');}else hide('pause');}
$('pauseButton').onclick=()=>setPause(true);$('continueButton').onclick=()=>setPause(false);$('saveQuit').onclick=title;
function help(from){helpFrom=from;show('help');if(from==='pause')hide('pause');}
$('howTo').onclick=()=>help('menu');$('helpPause').onclick=()=>help('pause');$('closeHelp').onclick=()=>{hide('help');if(helpFrom==='pause')show('pause');};
function displayGuide(){if(game.roaming)setPause(true);let standalone=navigator.standalone===true||matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches;$('displayStatus').textContent=standalone?'You are already using an app-style view. Turn your iPhone sideways for the most room to play.':'On iPhone, launch from your Home Screen for a view without Safari’s address and tab bars.';show('displayHelp');}
$('iphoneSetup').onclick=displayGuide;$('closeDisplayHelp').onclick=()=>hide('displayHelp');
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();resize();}else if(document.documentElement.requestFullscreen&&document.fullscreenEnabled!==false){await document.documentElement.requestFullscreen();resize();}else displayGuide();}catch{displayGuide();}};
$('controlSettings').onclick=()=>{show('controls');updateSettings();};$('closeControls').onclick=()=>hide('controls');
$('controlSize').onchange=()=>{settings.controlSize=$('controlSize').value;updateSettings();resetInput();};
$('controlReach').onchange=()=>{settings.controlReach=$('controlReach').value;updateSettings();resetInput();};
$('controlOpacity').oninput=()=>{settings.controlOpacity=Number($('controlOpacity').value);updateSettings();};
$('resetControls').onclick=()=>{settings.controlSize='medium';settings.controlReach='edge';settings.controlOpacity=35;updateSettings();resetInput();};

function bindStick(id,set){
 let el=$(id),stick=new FloatingStick(),box=null,thumb=el.querySelector('.stick-thumb'),ring=el.querySelector('.stick-ring');
 const clear=(pointer=stick.pointer)=>{if(!stick.end(pointer))return;set({x:0,y:0,power:0});el.classList.remove('active');thumb.style.transform='';thumb.style.left='';thumb.style.top='';ring.style.left='';ring.style.top='';};
 function paint(v){ring.style.left=v.baseX+'px';ring.style.top=v.baseY+'px';thumb.style.left=v.baseX+'px';thumb.style.top=v.baseY+'px';thumb.style.transform=`translate(-50%,-50%) translate(${v.thumbX}px,${v.thumbY}px)`;}
 el.addEventListener('pointerdown',e=>{if(stick.pointer!==null||paused||!game.roaming)return;e.preventDefault();box=el.getBoundingClientRect();if(!stick.start(e.pointerId,e.clientX-box.left,e.clientY-box.top,{w:box.width,h:box.height},uiLayout?.ring||44,uiLayout?.travel||36))return;el.setPointerCapture(e.pointerId);el.classList.add('active');set({x:0,y:0,power:0});paint({baseX:stick.base.x,baseY:stick.base.y,thumbX:0,thumbY:0});sound.boot();});
 el.addEventListener('pointermove',e=>{if(e.pointerId!==stick.pointer)return;e.preventDefault();let v=stick.move(e.pointerId,e.clientX-box.left,e.clientY-box.top);if(!v)return;set(stickVector(v.dx,v.dy,stick.travel,.09));paint(v);});
 for(let type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,e=>clear(e.pointerId));el.resetStick=()=>clear();
}
bindStick('moveStick',v=>move=v);bindStick('aimStick',v=>aim=v);
function resetInput(){keys.clear();mouse.down=false;move={x:0,y:0,power:0};aim={x:0,y:0,power:0};input.mx=0;input.my=0;input.fire=false;for(let id of ['moveStick','aimStick'])$(id)?.resetStick?.();}
$('world').addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;if(game.roaming&&!paused){mouse.down=true;mouse.seen=true;mouse.x=e.clientX;mouse.y=e.clientY;sound.boot();$('world').setPointerCapture(e.pointerId);}});
window.addEventListener('pointermove',e=>{if(e.pointerType!=='touch'){mouse.x=e.clientX;mouse.y=e.clientY;mouse.seen=true;}});window.addEventListener('pointerup',()=>{mouse.down=false;});window.addEventListener('pointercancel',()=>{mouse.down=false;});window.addEventListener('contextmenu',e=>e.preventDefault());
function action(name){if(!game.roaming||paused)return;sound.boot();if(name==='heal'&&!game.heal())toast(game.player.medkits?'Health is already full.':'No medkits left.');if(name==='dash')game.dash(input.mx,input.my);if(name==='reload')game.reload();if(name==='turret'&&!game.deploy())toast(game.player.turretCharges?'Two sentries are already deployed.':'Buy a sentry between waves.');updateHud();}
$('healButton').onclick=()=>action('heal');$('dashButton').onclick=()=>action('dash');$('turretButton').onclick=()=>action('turret');$('reloadButton').onclick=()=>action('reload');
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;let key=e.key.toLowerCase();if(game.roaming&&!paused&&[' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='escape'){if(!$('controls').classList.contains('hidden')){hide('controls');return;}if(!$('displayHelp').classList.contains('hidden')){hide('displayHelp');return;}if(!$('help').classList.contains('hidden')){$('closeHelp').click();return;}if(game.roaming)setPause(!paused);return;}keys.add(key);if(e.repeat||paused||!game.roaming)return;if(key==='enter'&&game.phase==='scavenge')$('collectContinue').click();if('123'.includes(key)&&key.length===1)game.switchWeapon(Number(key)-1);if(key==='r')action('reload');if(key==='e')action('heal');if(key==='q')action('turret');if(key===' ')action('dash');});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
$('weaponSlots').onclick=e=>{let b=e.target.closest('[data-slot]');if(b&&!paused){game.switchWeapon(Number(b.dataset.slot));updateHud();}};
function gamepads(){try{return navigator.getGamepads?.()||[]}catch{return []}}
function readInput(){input.mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+move.x;input.my=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+move.y;input.fire=false;input.angle=game.player.angle;
 if(mouse.seen&&!isTouch){let p=renderer.screenToWorld(mouse.x-viewOffset.x,mouse.y-viewOffset.y+20*renderer.scale);input.angle=Math.atan2(p.y-game.player.y,p.x-game.player.x);input.fire=mouse.down;}
 if(aim.power>.02){input.angle=aimAngle(aim.x,aim.y);if(settings.assist)input.angle=assistedAngle(input.angle,game.player,game.enemies);input.fire=true;}
 let pad=gamepads().find(p=>p?.connected);if(pad){let m=stickVector(pad.axes[0]||0,pad.axes[1]||0,1,.18),a=stickVector(pad.axes[2]||0,pad.axes[3]||0,1,.18);input.mx+=m.x;input.my+=m.y;if(a.power>.05){input.angle=aimAngle(a.x,a.y);if(settings.assist)input.angle=assistedAngle(input.angle,game.player,game.enemies);input.fire=true;}if(pad.buttons[7]?.pressed)input.fire=true;let bindings={0:'dash',2:'reload',3:'heal',4:'turret'};for(let [index,name]of Object.entries(bindings))if(pad.buttons[index]?.pressed&&!padPrevious[index])action(name);if(pad.buttons[1]?.pressed&&!padPrevious[1])game.switchWeapon((game.player.selected+1)%game.player.guns.length);if(pad.buttons[9]?.pressed&&!padPrevious[9])setPause(!paused);padPrevious=pad.buttons.map(b=>b.pressed);}
}
const waveNames=['THEY HEARD YOU ARRIVE','FOOTSTEPS IN THE GRASS','SOMETHING HEAVIER','WATCH THE WINDOWS','KEEP YOUR DISTANCE','THE HOUSE IS LISTENING','THE DEAD TEND THEIR OWN','HOLD YOUR GROUND','ONE MORE NIGHTMARE','THE GROUNDSKEEPER'];
function processEvents(){for(let event of game.events.splice(0)){sound.play(event.type,event.weapon);if(event.type==='hurt'){renderer.shake=settings.low?0:7;if(navigator.vibrate&&isTouch)navigator.vibrate(25);}if(event.type==='wave'){$('bannerTitle').textContent='WAVE '+String(game.wave).padStart(2,'0');$('bannerSub').textContent=waveNames[game.wave-1];show('waveBanner');bannerTimer=3;hide('bossHud');}if(event.type==='scavenge'){hide('waveBanner');hide('tutorial');save();}if(event.type==='clear'){hide('waveBanner');hide('tutorial');shopTab='arsenal';records.best=Math.max(records.best,game.wave);write(META,records);openShop();save();}if(event.type==='dead'||event.type==='won')endRun(event.type==='won');}}
function updateHud(){let p=game.player,w=game.weapon,g=game.gun;$('survivorName').textContent=game.character.toUpperCase();$('healthText').textContent=Math.ceil(p.hp)+' / '+p.maxHp;$('healthBar').style.width=(p.hp/p.maxHp*100)+'%';$('healthBar').style.background=p.hp<p.maxHp*.3?'#eaa08b':'var(--lime)';$('cashText').textContent=p.cash;$('armorText').textContent=p.armor?'ARMOR '+p.armor:'';$('waveText').textContent='WAVE '+String(game.wave).padStart(2,'0');let total=WAVE_TOTALS[game.wave-1]||14;$('remaining').textContent=game.phase==='scavenge'?'All clear · Collect supplies':(total-game.waveKills)+' remaining';$('collectContinue').classList.toggle('hidden',game.phase!=='scavenge');$('waveBar').style.width=game.waveKills/total*100+'%';$('medCount').textContent='HEAL · '+p.medkits;$('healButton').disabled=p.medkits===0;$('turretCount').textContent='SENTRY · '+p.turretCharges;$('turretButton').classList.toggle('unavailable',p.turretCharges===0);$('turretButton').disabled=p.turretCharges===0;$('dashText').textContent=p.dash>0?p.dash.toFixed(1)+'s':'DASH';$('dashButton').classList.toggle('cooldown',p.dash>0);$('ammoText').textContent=w.melee?'∞':g.clip+' / '+(w.ammo==='free'?'∞':p.ammo[w.ammo]);$('reloadText').textContent=g.reload>0?'RELOADING':(!w.melee&&g.clip===0&&w.ammo!=='free'&&p.ammo[w.ammo]===0?'EMPTY':'↻ RELOAD');$('reloadButton').classList.toggle('reloading',g.reload>0);$('reloadButton').disabled=!!w.melee;let signature=p.guns.map(g=>g.id+g.level).join(',')+p.selected;if(signature!==hudSignature){hudSignature=signature;$('weaponSlots').innerHTML=[0,1,2].map((i)=>{let gun=p.guns[i];return gun?`<button class="weapon-slot ${p.selected===i?'active':''}" data-slot="${i}" aria-label="Equip ${WEAPONS[gun.id].name}"><span class="slot-number">${i+1}</span>${WEAPONS[gun.id].name}<small>${gun.level?'✦'.repeat(gun.level)+' UPGRADED':i===0?'UNLIMITED RESERVE':WEAPONS[gun.id].tag}</small></button>`:`<button class="weapon-slot empty" disabled><span class="slot-number">${i+1}</span>Empty slot<small>BUY BETWEEN WAVES</small></button>`;}).join('');}
 let boss=game.enemies.find(e=>e.type==='boss'&&e.hp>0);if(boss){show('bossHud');$('bossBar').style.width=boss.hp/boss.maxHp*100+'%';}else hide('bossHud');}
const symbols={RIFLE:'━╸',SHOTGUN:'═╸',SMG:'┯━',CONTROL:'❄',PIERCING:'↠',FLAME:'♨',EXPLOSIVE:'◉',CHAIN:'ϟ',SIDEARM:'┓',MELEE:'╱'};
function openShop(){resetInput();show('shop');renderShop();}
function card({tag,name,desc,stats,label,action,disabled=false,active=false,symbol='✦'}){return `<article class="item-card ${active?'equipped':''}"><div class="item-top"><span class="item-tag">${tag}</span><span class="weapon-symbol">${symbol}</span></div><h3>${name}</h3><p>${desc}</p>${stats?`<div class="item-stats">${stats}</div>`:''}<button class="buy-button" ${disabled?'disabled':''} data-buy="${action}">${label}</button></article>`;}
function renderShop(){let p=game.player;$('clearLabel').textContent='WAVE '+String(game.wave).padStart(2,'0')+' COMPLETE';$('shopCash').textContent='◆ '+p.cash;$('waveReward').textContent='+'+game.bonus+' wave bonus';$('shopHealth').textContent='Health '+Math.ceil(p.hp)+' / '+p.maxHp;$('nextWave').innerHTML='Begin wave '+String(game.wave+1).padStart(2,'0')+' <span>→</span>';for(let b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===shopTab);b.setAttribute('aria-selected',String(b.dataset.tab===shopTab));}
 if(shopTab==='arsenal'){$('shopAdvice').textContent=p.guns.length<3?'Your sidearm stays. Choose two extra weapons.':'New purchases replace '+WEAPONS[p.guns[p.selected===0?2:p.selected].id].name+'.';$('shopItems').innerHTML=Object.entries(WEAPONS).filter(([id,w])=>w.price>0).map(([id,w])=>{let owned=p.guns.findIndex(g=>g.id===id);let label=owned>=0?(owned===p.selected?'Equipped':'Select weapon'):'◆ '+w.price+(p.guns.length>=3?' · Replace slot '+(p.selected===0?3:p.selected+1):' · Equip');return card({tag:w.tag,name:w.name,desc:w.desc,stats:`${w.damage}${w.pellets?' × '+w.pellets:''} DMG  ·  ${w.clip} MAG  ·  ${w.ammo.toUpperCase()}`,label,action:owned>=0?'equip:'+owned:id,disabled:owned<0&&p.cash<w.price,active:owned>=0,symbol:symbols[w.tag]});}).join('');}
 if(shopTab==='upgrades'){$('shopAdvice').textContent='Each upgrade: +30% base damage, +2 magazine, faster firing.';$('shopItems').innerHTML=p.guns.map((g,i)=>{let w=WEAPONS[g.id],cost=65+g.level*65;return card({tag:i===p.selected?'SELECTED WEAPON':'SLOT '+(i+1),name:w.name,desc:g.level<3?'Give this weapon more stopping power. Upgrades last for this run.':'Fully upgraded. Ready for whatever the hollow sends.',stats:'LEVEL '+g.level+' / 3  ·  '+Math.round(w.damage*(1+g.level*.3)*game.char.damage)+' DAMAGE',label:g.level<3?'◆ '+cost+' · Upgrade':'Fully upgraded',action:'upgrade:'+i,disabled:g.level>=3||p.cash<cost,symbol:symbols[w.tag],active:i===p.selected});}).join('');}
 if(shopTab==='supplies'){$('shopAdvice').textContent='Sentries last 40 seconds. Two can be active at once.';let items=[{tag:'AMMUNITION',name:'Ammo cache',desc:'Adds half the maximum reserve for every ammunition type.',stats:`LIGHT ${p.ammo.light} · SHELL ${p.ammo.shell} · HEAVY ${p.ammo.heavy} · EXP ${p.ammo.explosive}`,id:'ammo',cost:45,symbol:'▥'}, {tag:'HEALTH',name:'Field medkit',desc:'Restore '+(game.character==='wren'?85:60)+' health during a wave. Carry up to four.',stats:p.medkits+' / 4 CARRIED',id:'medkit',cost:55,symbol:'✚',full:p.medkits>=4},{tag:'RECOVERY',name:'Patch up',desc:'Restore all your health before the next wave.',stats:Math.ceil(p.hp)+' / '+p.maxHp+' HEALTH',id:'repair',cost:65,symbol:'♡',full:p.hp>=p.maxHp},{tag:'PROTECTION',name:'Salvaged armor',desc:'Reduce incoming damage by another 3 points.',stats:p.armor+' / 12 DAMAGE REDUCTION',id:'armor',cost:100+p.armor*7,symbol:'⬡',full:p.armor>=12},{tag:'DEPLOYABLE',name:'Pocket sentry',desc:'Drop a companion turret during combat. Hex builds stronger ones.',stats:p.turretCharges+' / 3 CARRIED',id:'turret',cost:90,symbol:'♜',full:p.turretCharges>=3}];$('shopItems').innerHTML=items.map(o=>card({...o,label:o.full?'Fully stocked':'◆ '+o.cost+' · Buy',action:o.id,disabled:o.full||p.cash<o.cost})).join('');}}
for(let b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{shopTab=b.dataset.tab;renderShop();$('shopItems').scrollTop=0;};
$('shopItems').onclick=e=>{let b=e.target.closest('[data-buy]');if(!b||b.disabled)return;let a=b.dataset.buy,result;if(a.startsWith('upgrade:'))result=game.upgrade(Number(a.split(':')[1]));else if(a.startsWith('equip:')){game.switchWeapon(Number(a.split(':')[1]));result={ok:true,message:'Weapon selected.'};}else result=game.purchase(a);toast(result.message);renderShop();updateHud();save();processEvents();};
$('collectContinue').onclick=()=>{if(paused)return;if(game.enterShop()){processEvents();updateHud();}};
$('nextWave').onclick=()=>{hide('shop');resetInput();game.beginWave();processEvents();save();updateHud();};
function endRun(won){paused=false;resetInput();for(let id of ['shop','pause','help','controls','displayHelp','waveBanner','tutorial'])hide(id);remove(SAVE);records.best=Math.max(records.best,won?10:game.wave-1);if(won)records.wins++;write(META,records);$('endEyebrow').textContent=won?'FIRST LIGHT AT HOLLOW HOUSE':'THE HOLLOW REMEMBERS';$('endTitle').textContent=won?'You made it to dawn.':'A light goes out.';$('endDescription').textContent=won?'The groundskeeper has fallen. For tonight, the house is yours.':'Try a new weapon, keep an escape route, and return stronger.';$('endWave').textContent=won?10:game.wave-1;$('endKills').textContent=game.kills;let t=Math.floor(game.time);$('endTime').textContent=Math.floor(t/60)+':'+String(t%60).padStart(2,'0');show('end');}
$('retry').onclick=()=>{remove(SAVE);$('resume').classList.add('hidden');begin();};$('backTitle').onclick=title;
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();if(game.roaming)setPause(true);resetInput();}});window.addEventListener('pagehide',save);window.addEventListener('blur',()=>{resetInput();if(game.roaming)setPause(true);});
function frame(now){if(settings.low&&now-lastTime<32){requestAnimationFrame(frame);return;}let dt=Math.min(.05,(now-lastTime)/1000||.016);lastTime=now;try{if(game.roaming&&!paused){readInput();if(!paused)game.update(dt,input);processEvents();bannerTimer-=dt;if(bannerTimer<=0)hide('waveBanner');tutorialTimer-=dt;if(tutorialTimer<=0)hide('tutorial');saveTimer+=dt;if(saveTimer>5){save();saveTimer=0;}}else if(paused&&gamepads().some(p=>p?.connected)){readInput();}
 if(now-lastHud>100&&game.phase!=='menu'){updateHud();lastHud=now;}renderer.draw(game,now,game.phase==='menu');}catch(err){console.error(err);setPause(true);toast('The run was paused after an error. Reload to restore your save.');}requestAnimationFrame(frame);}
title();requestAnimationFrame(frame);
